-- LENT : fonction sur la colonne filtree, l'index sur email n'est pas utilise
SELECT * FROM utilisateurs WHERE lower(email) = 'ada@dev.io';

-- RAPIDE : on normalise a l'ecriture et on filtre sur la colonne indexee
-- (email stocke deja en minuscules), et on ne lit que les colonnes utiles
SELECT id, nom FROM utilisateurs WHERE email = 'ada@dev.io';
